/**
 * Action 02 Prompt Module for tx-5-imp-1 Agent
 * 
 * Contract: tx_5_imp_1
 * Title: 課題抽出から既存ツール連携・確認までの自律実行
 * 
 * Action 02: 優先度・カテゴリを自動判定する
 * 
 * This module generates prompts for the AI agent to validate and judge
 * the priority and category of extracted issues, preparing them for
 * integration with existing tools (Jira, Asana, etc.).
 */

export const ACTION_02_PROMPT_VERSION = "1.0.0";

export interface IssueData {
  id: string;
  title: string;
  description: string;
  extractedAt: string;
  source: string;
}

export interface PriorityJudgmentContext {
  issues: IssueData[];
  priorityRules: PriorityRule[];
  categoryDefinitions: CategoryDefinition[];
  historicalIssues: HistoricalIssueReference[];
}

export interface PriorityRule {
  ruleId: string;
  name: string;
  criteria: string[];
  priorityLevel: "critical" | "high" | "medium" | "low";
  confidenceThreshold: number;
}

export interface CategoryDefinition {
  categoryId: string;
  name: string;
  keywords: string[];
  description: string;
}

export interface HistoricalIssueReference {
  issueId: string;
  title: string;
  category: string;
  priority: string;
  resolvedAt: string;
}

export interface JudgmentResult {
  issueId: string;
  originalTitle: string;
  assignedPriority: "critical" | "high" | "medium" | "low";
  priorityConfidence: number;
  assignedCategory: string;
  categoryConfidence: number;
  reasoning: string;
  requiresEscalation: boolean;
  escalationReason?: string;
}

export interface Action02PromptInput {
  context: PriorityJudgmentContext;
  targetIssues: IssueData[];
  organizationContext?: string;
  previousJudgments?: JudgmentResult[];
}

export interface Action02PromptOutput {
  systemPrompt: string;
  userPrompt: string;
  expectedOutputFormat: string;
}

/**
 * Builds the system and user prompts for Action 02: Priority and Category Judgment
 * 
 * This function constructs prompts that guide the AI agent to:
 * 1. Validate extracted issue data format and content
 * 2. Automatically judge priority level based on defined rules
 * 3. Automatically assign category based on issue characteristics
 * 4. Assess confidence levels for both judgments
 * 5. Identify issues requiring human escalation
 * 6. Provide reasoning for all judgments
 * 
 * @param input - The input context and issues for judgment
 * @returns Object containing system prompt, user prompt, and expected output format
 */
export function buildAction02Prompt(input: Action02PromptInput): Action02PromptOutput {
  const {
    context,
    targetIssues,
    organizationContext = "",
    previousJudgments = [],
  } = input;

  const systemPrompt = buildSystemPrompt(context, organizationContext);
  const userPrompt = buildUserPrompt(targetIssues, context, previousJudgments);
  const expectedOutputFormat = buildExpectedOutputFormat();

  return {
    systemPrompt,
    userPrompt,
    expectedOutputFormat,
  };
}

function buildSystemPrompt(
  context: PriorityJudgmentContext,
  organizationContext: string
): string {
  const priorityRulesDescription = context.priorityRules
    .map(
      (rule) =>
        `- ${rule.name} (${rule.priorityLevel}): ${rule.criteria.join(", ")}`
    )
    .join("\n");

  const categoryDefinitionsDescription = context.categoryDefinitions
    .map(
      (cat) =>
        `- ${cat.name}: ${cat.description} (Keywords: ${cat.keywords.join(", ")})`
    )
    .join("\n");

  return `You are an expert issue classification and prioritization system for a morning report management platform.

Your role is to validate extracted issue data and automatically assign priority levels and categories based on predefined rules and organizational context.

## Priority Rules

${priorityRulesDescription}

## Category Definitions

${categoryDefinitionsDescription}

## Classification Guidelines

1. **Priority Judgment**: Evaluate each issue against the priority rules. Consider:
   - Impact scope (single person, team, department, organization-wide)
   - Urgency (immediate action needed vs. can wait)
   - Business criticality
   - Risk level if not addressed

2. **Category Assignment**: Match issues to categories based on:
   - Keyword matching
   - Issue description analysis
   - Historical pattern recognition
   - Organizational context

3. **Confidence Assessment**: Rate your confidence (0.0 to 1.0) for both priority and category assignments based on:
   - Clarity of issue description
   - Match strength with rules/categories
   - Presence of ambiguous signals

4. **Escalation Identification**: Flag issues for human review if:
   - Confidence is below 0.7 for either judgment
   - Issue spans multiple categories
   - Issue doesn't fit standard priority rules
   - Issue requires organizational policy interpretation

## Organization Context

${organizationContext || "Standard organizational context applies."}

## Output Requirements

Provide structured JSON output with clear reasoning for each judgment. Be consistent with previous judgments where applicable.`;
}

function buildUserPrompt(
  targetIssues: IssueData[],
  context: PriorityJudgmentContext,
  previousJudgments: JudgmentResult[]
): string {
  const issuesJson = JSON.stringify(targetIssues, null, 2);

  const previousJudgmentsContext =
    previousJudgments.length > 0
      ? `\n\n## Previous Similar Judgments (for consistency)\n\n${JSON.stringify(
          previousJudgments.slice(0, 5),
          null,
          2
        )}`
      : "";

  const historicalContext =
    context.historicalIssues.length > 0
      ? `\n\n## Historical Issue References\n\nRecent similar issues:\n${context.historicalIssues
          .slice(0, 10)
          .map(
            (issue) =>
              `- "${issue.title}" (Category: ${issue.category}, Priority: ${issue.priority})`
          )
          .join("\n")}`
      : "";

  return `Please analyze and judge the following extracted issues:

${issuesJson}

${previousJudgmentsContext}

${historicalContext}

For each issue, provide:
1. Assigned priority level (critical/high/medium/low)
2. Priority confidence score (0.0-1.0)
3. Assigned category
4. Category confidence score (0.0-1.0)
5. Clear reasoning for both judgments
6. Whether escalation to human review is required
7. If escalation needed, the specific reason

Consider:
- Issue severity and impact
- Organizational priorities
- Historical patterns
- Consistency with previous judgments
- Any ambiguities that warrant escalation

Output as valid JSON array of judgment results.`;
}

function buildExpectedOutputFormat(): string {
  return `[
  {
    "issueId": "string",
    "originalTitle": "string",
    "assignedPriority": "critical" | "high" | "medium" | "low",
    "priorityConfidence": number (0.0-1.0),
    "assignedCategory": "string",
    "categoryConfidence": number (0.0-1.0),
    "reasoning": "string (detailed explanation of judgments)",
    "requiresEscalation": boolean,
    "escalationReason": "string (optional, only if requiresEscalation is true)"
  }
]`;
}
